def _backfill() -> None:
    """Consent already recorded on members becomes their first consent record, and the
    academy's belts get the curriculum (skills, requirements, Arabic names)."""
    bind = op.get_bind()
    bind.execute(
        sa.text(
            "INSERT INTO media_consents (member_id, internal_records, social_media,"
            " website_marketing, signed_by_name, signed_at, from_portal, notes)"
            " SELECT id, 1, 1, 1, COALESCE(guardian_name, CONCAT(first_name, ' ', last_name)),"
            " created_at, 0, 'Recorded at registration' FROM members WHERE media_consent = 1"
        )
    )
    belts = bind.execute(sa.text("SELECT id, sort_order FROM belt_ranks ORDER BY sort_order")).all()
    if len(belts) != len(BELT_KEYS):
        return  # not the standard Kajukenbo belts: leave the curriculum to the academy
    has_skills = bind.execute(sa.text("SELECT COUNT(*) FROM belt_skills")).scalar()
    for (belt_id, _), key in zip(belts, BELT_KEYS, strict=True):
        name_ar, _stripe, stripe_ar, classes, weeks, evals = BELT_EXTRAS[key]
        bind.execute(
            sa.text(
                "UPDATE belt_ranks SET name_ar = :n, bjj_stripe_ar = :s, min_classes = :c,"
                " min_weeks = :w, min_evaluations = :e WHERE id = :id"
            ),
            {"n": name_ar, "s": stripe_ar, "c": classes, "w": weeks, "e": evals, "id": belt_id},
        )
        if has_skills:
            continue
        for track in ("kickboxing", "jiujitsu", "self_defence"):
            for order, (category, name) in enumerate(SKILLS.get(f"{track}:{key}", [])):
                bind.execute(
                    sa.text(
                        "INSERT INTO belt_skills (belt_rank_id, track, category, name, sort_order,"
                        " is_active) VALUES (:b, :t, :c, :n, :o, 1)"
                    ),
                    {"b": belt_id, "t": track, "c": category, "n": name, "o": order},
                )


